27	    this.add.image(cx, 180, KEYS.ui_title_logo);
28	
29	    this.add
30	      .text(cx, 330, t('menu_subtitle'), {
31	        fontFamily: 'system-ui, sans-serif',
32	        fontSize: '24px',
33	        color: '#3a444d',
34	      })
35	      .setOrigin(0.5);
36	
37	    createButton(this, {
38	      x: cx,
39	      y: 450,
40	      texture: KEYS.ui_btn_play,
41	      label: t('menu_play'),
42	      onClick: () => this.scene.start(SceneKey.Game),
43	    });
44	
45	    this.add
46	      .text(cx, 550, t('menu_hint'), {
47	        fontFamily: 'system-ui, sans-serif',
48	        fontSize: '20px',
49	        color: '#3a444d',
50	      })
51	      .setOrigin(0.5);
52	
53	    this.buildMuteToggle();
54	  }
55	
56	  private buildMuteToggle(): void {
57	    const muteBtn = this.add
58	      .image(GAME_WIDTH - 52, 52, this.muteTexture())
59	      .setInteractive({ useHandCursor: true });
60	
61	    const label = this.add
62	      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
63	        fontFamily: 'system-ui, sans-serif',
64	        fontSize: '14px',
65	        color: '#9fb0bd',
66	      })
67	      .setOrigin(0.5, 0);
68	
69	    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
70	      AudioManager.toggle(this.sound);
71	      muteBtn.setTexture(this.muteTexture());
72	      label.setText(this.muteLabel());
73	    });
74	  }
75	
76	  private muteTexture(): string {
77	    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
78	  }
79	
80	  private muteLabel(): string {
81	    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
82	  }
83	}
